const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
    // 1. Define geometry (Pedrógão Grande, Portugal)
    const pedrogaoGrande = ee.Geometry.Point([-8.1667, 39.9167]);
    const region = pedrogaoGrande.buffer(10000); // 10km buffer

    // 2. Define date range
    const startDate = '2017-06-16';
    const endDate = '2017-06-20';

    // 3. Load VIIRS active fire data
    const fireCollection = ee.ImageCollection('NOAA/VIIRS/001/VNP14IMGDL')
        .filterDate(startDate, endDate)
        .filterBounds(region);

    // Check collection size
    const collectionSize = fireCollection.size().getInfo();
    console.log(`Number of VIIRS images: ${collectionSize}`);

    if (collectionSize === 0) {
        // No images found
        console.log('C1: No fire detection data available for the given date/location.');
        console.log('<answer>C1</answer>');
        return;
    }

    // 4. Process fire data
    // Create a composite with maximum FireMask value (to capture any fire pixels)
    const composite = fireCollection.select('FireMask').max();

    // Create fire mask (FireMask >= 4 indicates fire)
    const fireMask = composite.gte(4);

    // Count fire pixels in the region
    const fireCount = fireMask.reduceRegion({
        reducer: ee.Reducer.sum(),
        geometry: region,
        scale: 1000,
        maxPixels: 1e9
    }).get('FireMask').getInfo();

    console.log(`Fire pixel count: ${fireCount}`);

    // 5. Validate and output answer
    if (fireCount === null || fireCount === undefined) {
        console.log('C3: Could not calculate fire count.');
        console.log('<answer>C3</answer>');
    } else if (fireCount > 0) {
        console.log('A: Fire detected.');
        console.log('<answer>A</answer>');
    } else {
        console.log('B: No fire detected.');
        console.log('<answer>B</answer>');
    }
}

async function initEE() {
    await new Promise((resolve, reject) => {
        ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
    });
    await new Promise((resolve, reject) => {
        ee.initialize(null, null, resolve, reject);
    });
    await runAnalysis();
}

initEE();
